CREATE TYPE named_source_pair AS (item integer,label text);
CREATE FUNCTION named_source_rows() RETURNS SETOF named_source_pair LANGUAGE sql AS $$SELECT ROW(7,'one')::named_source_pair UNION ALL SELECT NULL::named_source_pair$$;
CREATE FUNCTION named_source_table() RETURNS TABLE(value named_source_pair) LANGUAGE sql AS $$SELECT ROW(8,'two')::named_source_pair UNION ALL SELECT NULL::named_source_pair$$;
CREATE TABLE named_source_audit(value integer);
CREATE FUNCTION named_source_write() RETURNS SETOF named_source_pair LANGUAGE sql VOLATILE AS $$INSERT INTO named_source_audit VALUES (1); SELECT ROW(9,'sql')::named_source_pair$$;
CREATE FUNCTION named_source_pl() RETURNS SETOF named_source_pair LANGUAGE plpgsql AS $$BEGIN RETURN NEXT ROW(10,'pl')::named_source_pair; RETURN NEXT NULL; END$$;
CREATE FUNCTION named_source_pl_table() RETURNS TABLE(value named_source_pair) LANGUAGE plpgsql AS $$BEGIN value:=ROW(11,'out')::named_source_pair; RETURN NEXT; END$$;
SELECT * FROM named_source_rows() WITH ORDINALITY;
SELECT * FROM named_source_table() WITH ORDINALITY;
SELECT * FROM named_source_write();
SELECT * FROM named_source_pl() WITH ORDINALITY;
SELECT * FROM named_source_pl_table();
SELECT count(*) FROM named_source_audit;
SELECT * FROM ROWS FROM(named_source_rows(),generate_series(20,22)) WITH ORDINALITY;
SELECT n,a,b FROM (VALUES(1),(2)) AS source(n),LATERAL named_source_rows() AS result(a,b) ORDER BY n,a NULLS LAST;
SELECT named_source_rows();
CREATE TABLE named_source_conflict(id integer PRIMARY KEY,value named_source_pair);
CREATE FUNCTION named_source_trigger() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN NEW.value:=ROW((OLD.value).item+1,(NEW.value).label)::named_source_pair; RETURN NEW; END$$;
CREATE TRIGGER named_source_update BEFORE UPDATE ON named_source_conflict FOR EACH ROW EXECUTE FUNCTION named_source_trigger();
INSERT INTO named_source_conflict VALUES (1,ROW(3,'old')::named_source_pair);
INSERT INTO named_source_conflict VALUES (1,ROW(20,'new')::named_source_pair) ON CONFLICT(id) DO UPDATE SET value=EXCLUDED.value RETURNING (value).item,(value).label;
DROP TABLE named_source_conflict;
DROP FUNCTION named_source_trigger();
DROP FUNCTION named_source_rows();
DROP FUNCTION named_source_table();
DROP FUNCTION named_source_write();
DROP FUNCTION named_source_pl();
DROP FUNCTION named_source_pl_table();
DROP TABLE named_source_audit;
DROP TYPE named_source_pair;
